class G:
 def __init__(self,a=0,b=0):
  if isinstance(a,G):self.a,self.b=a.a,a.b
  else:self.a,self.b=Q(a),Q(b)
 def __add__(self,o):o=G(o);return G(self.a+o.a,self.b+o.b)
 __radd__=__add__
 def __neg__(self):return G(-self.a,-self.b)
 def __sub__(self,o):return self+-G(o)
 def __rsub__(self,o):return G(o)+-self
 def __mul__(self,o):o=G(o);return G(self.a*o.a-self.b*o.b,self.a*o.b+self.b*o.a)
 __rmul__=__mul__
 def __truediv__(self,o):o=G(o);d=o.a*o.a+o.b*o.b;assert d;return self*G(o.a/d,-o.b/d)
 def __rtruediv__(self,o):return G(o)/self
 def __pow__(self,n):
  if n<0:return (1/self)**(-n)
  z=G(1)
  for _ in range(n):z=z*self
  return z
 def __bool__(self):return bool(self.a or self.b)
 def __eq__(self,o):o=G(o);return self.a==o.a and self.b==o.b
 def __str__(self):return str(self.a)if not self.b else f'({self.a})+({self.b})*I'
N=0
def ck(a,b,label):
 global N
 assert a==b,label
 N+=1
def atom(n,i=None,co=1):
 e=[0]*n
 if i is not None:e[i]=1
 return {tuple(e):G(co)}if co else{}
def power(p,n):
 out=atom(len(next(iter(p),())),co=1)
 for _ in range(n):out=mul(out,p)
 return out
def parse(text,names=()):
 zero=(0,)*len(names)
 def go(x):
  if isinstance(x,ast.Constant):return {zero:G(x.value)}if x.value else{}
  if isinstance(x,ast.Name):
   if x.id=='I':return {zero:G(0,1)}
   return atom(len(names),names.index(x.id))
  if isinstance(x,ast.UnaryOp):return scale(go(x.operand),-1)if isinstance(x.op,ast.USub)else go(x.operand)
  a=go(x.left)
  if isinstance(x.op,ast.Pow):
   exponent=ast.literal_eval(x.right);out={zero:G(1)}
   for _ in range(exponent):out=mul(out,a)
   return out
  b=go(x.right)
  if isinstance(x.op,ast.Add):return add(a,b)
  if isinstance(x.op,ast.Sub):return add(a,scale(b,-1))
  if isinstance(x.op,ast.Mult):return mul(a,b)
  if isinstance(x.op,ast.Div):assert set(b)=={zero};return scale(a,1/b[zero])
  raise ValueError(ast.dump(x))
 return go(ast.parse(str(text),mode='eval').body)
def num(t):return parse(t).get((),G())
def mat(a):return [[num(v)for v in row]for row in a]
def mm(a,b):return [[sum((v*b[k][j]for k,v in enumerate(row)if v),G())for j in range(len(b[0]))]for row in a]
def ident(n):return [[G(i==j)for j in range(n)]for i in range(n)]
def cols(columns):return list(map(list,zip(*columns)))
def mv(A,v):return [sum((a*x for a,x in zip(row,v)if a and x),G())for row in A]
