Wb=mat(r['all3_fundamentalfield_wedges_equalSym2_modEuler']['block_coordinates']);Wbi=mat(r['all3_fundamentalfield_wedges_equalSym2_modEuler']['block_inverse']);ck(Wco[:3],Wb,'wedge equalsSym2');ck(mm(Wb,Wbi),ident(3),'wedgeinverse1');ck(mm(Wbi,Wb),ident(3),'wedgeinverse2')
